// GET: read-only venue list, reassembled from D1's `venues` table (see
// migrations/005_venues.sql) into the shape data/venues.json used to
// produce back when it was the source of truth — js/app.js and
// functions/api/checkin.js both read live from D1 now (this endpoint and a
// direct query respectively); data/venues.json is a mirror, regenerated by
// scripts/export-venues.js.
//
// POST: an owner submitting a brand-new venue ("List your venue" on the
// flame sheet, js/app.js openVenueSubmitForm()). Inserts with pin_status
// 'pending' and lat/lng NULL — there is no map pin until Kar looks at the
// submitted Google Maps link and sets real coordinates by hand (see
// functions/api/pending.js and migrations/009_pin_status.sql). No lat/lng
// input exists anywhere in this request; the server never accepts
// coordinates from an owner, submitting or editing.
//
// venuesFallback is bundled into the Function at build time (see the 2026-08
// outage where a deploy referenced a column that didn't exist on production
// yet — every request 500'd with nothing to show). If the D1 query throws
// for any reason, we serve this mirror instead of an error so the app still
// has something on the map; the response is marked "stale" so the frontend
// can tell the user, and never cached, so the very next request tries D1
// fresh rather than being stuck on stale data for a Cache-Control window.
// The fallback only ever applies to GET — a POST during a D1 outage just
// fails, there's nothing sane to fall back to for a write.
import venuesFallback from '../../data/venues.json';
import { getSessionUser } from './_auth.js';
import {
  SIMPLE_FIELDS, REQUIRED_SIMPLE_FIELDS, VENUE_TYPES, MAX_LEN, isUrlish,
  validateHours, validateContact, validateParking, validateSignature,
} from './_venue-validation.js';

async function handleGet(context) {
  try {
    const db = context.env.DB;
    const cache = caches.default;
    const cacheKey = new Request(context.request.url, { method: 'GET' });

    const cached = await cache.match(cacheKey);
    if (cached) return cached;

    // 'rejected' (see functions/api/venues/[id]/reject.js) is deliberately
    // excluded here — a turned-down submission isn't deleted, but it also
    // shouldn't be publicly browsable. The owner still sees it via the
    // unfiltered /api/my-venues -> "Manage your venue" (js/app.js)
    const rows = await db.prepare(
      `SELECT id, name, short_name, name_lo, type, lat, lng, area, short,
              description, photos, hours, hours_note, contact, parking, links,
              verified, status, source, signature, pin_status, vibe
       FROM venues WHERE pin_status != 'rejected' ORDER BY rowid`
    ).all();

    const venues = rows.results.map((r) => {
      const v = {
        id: r.id,
        name: r.name,
        short_name: r.short_name,
        name_lo: r.name_lo,
        type: r.type,
        lat: r.lat,
        lng: r.lng,
        area: r.area,
        short: r.short,
        description: r.description,
        photos: JSON.parse(r.photos || '[]'),
        hours: r.hours ? JSON.parse(r.hours) : null,
        hours_note: r.hours_note,
        links: r.links ? JSON.parse(r.links) : {},
        verified: !!r.verified,
        source: r.source,
        pin_status: r.pin_status,
      };
      // contact/parking/status are omitted entirely when absent, matching
      // data/venues.json's convention — never emitted as null
      if (r.contact !== null) v.contact = JSON.parse(r.contact);
      if (r.parking !== null) v.parking = JSON.parse(r.parking);
      if (r.status !== null) v.status = r.status;
      if (r.signature !== null) v.signature = JSON.parse(r.signature);
      if (r.vibe !== null) v.vibe = JSON.parse(r.vibe);
      return v;
    });

    const response = Response.json(
      { venues },
      { headers: { 'Cache-Control': 'public, max-age=300' } }
    );
    context.waitUntil(cache.put(cacheKey, response.clone()));
    return response;
  } catch (e) {
    // still logged so the real cause (e.g. a migration that never ran
    // against --remote) stays diagnosable — see CLAUDE.md's workflow rules
    console.error('venues fetch failed, serving bundled fallback:', e);
    return Response.json(
      { venues: venuesFallback.venues.filter(v => v.pin_status !== 'rejected'), stale: true },
      { headers: { 'Cache-Control': 'no-store' } }
    );
  }
}

function slugify(name) {
  const base = name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 50);
  return base || 'venue';
}

// appends -2, -3, ... on collision — ids are short human-readable slugs
// (see existing venues in data/venues.json), not random, so two "Baron"
// submissions read as baron / baron-2, not a UUID soup
async function uniqueVenueId(db, name) {
  const base = slugify(name);
  let id = base;
  let n = 1;
  while (await db.prepare('SELECT 1 FROM venues WHERE id = ?').bind(id).first()) {
    n++;
    id = `${base}-${n}`;
  }
  return id;
}

// same field rules as validateSimpleFields in _venue-validation.js, but for
// a fresh row every SIMPLE_FIELD is being set at once (not a sparse PATCH),
// so this returns a plain {field: value} object instead of pushing
// "field = ?" pairs — name/area/type are required here in a way PATCH never
// requires them (PATCH only validates a field if it's present at all)
function validateCreateFields(body, errors) {
  const out = {};
  for (const field of SIMPLE_FIELDS) {
    const v = body[field];
    if (field === 'type') {
      if (!VENUE_TYPES.includes(v)) { errors.type = 'must be bar, cafe, or venue'; continue; }
      out.type = v;
      continue;
    }
    const trimmed = typeof v === 'string' ? v.trim() : '';
    if (REQUIRED_SIMPLE_FIELDS.has(field) && !trimmed) { errors[field] = `${field} can't be empty`; continue; }
    if (trimmed.length > MAX_LEN[field]) {
      errors[field] = `must be ${MAX_LEN[field]} characters or fewer`;
      continue;
    }
    out[field] = trimmed;
  }
  return out;
}

async function handlePost(context) {
  try {
    const user = await getSessionUser(context);
    if (!user) return Response.json({ ok: false, need_auth: true }, { status: 401 });

    const body = await context.request.json().catch(() => null);
    if (!body || typeof body !== 'object') {
      return Response.json({ ok: false, error: 'invalid body' }, { status: 400 });
    }

    const errors = {};
    const fields = validateCreateFields(body, errors);

    // the one field the normal edit form doesn't require — no lat/lng
    // input exists anywhere, so this Maps link is the only lead Kar has to
    // go place the pin from (see functions/api/pending.js)
    const mapsUrl = typeof body.maps_url === 'string' ? body.maps_url.trim() : '';
    if (!mapsUrl) errors.maps_url = 'Google Maps link is required';
    else if (!/^https?:\/\/\S+$/i.test(mapsUrl)) errors.maps_url = "doesn't look like a link";

    const links = { maps: mapsUrl };
    if ('links' in body) {
      const l = body.links;
      if (typeof l !== 'object' || l === null || Array.isArray(l)) {
        errors.links = 'invalid links';
      } else {
        for (const key of ['facebook', 'website']) {
          if (!(key in l)) continue;
          const v = typeof l[key] === 'string' ? l[key].trim() : '';
          if (!isUrlish(v)) { errors.links = `${key} doesn't look like a link`; break; }
          links[key] = v;
        }
      }
    }

    const hours = validateHours(body.hours ?? null, errors);
    const contact = validateContact(body.contact ?? null, errors);
    const parking = validateParking(body.parking ?? null, errors);
    const signature = validateSignature(body.signature ?? null, errors);

    if (Object.keys(errors).length > 0) {
      return Response.json({ ok: false, errors }, { status: 400 });
    }

    const db = context.env.DB;
    const id = await uniqueVenueId(db, fields.name);
    const nowIso = new Date().toISOString();
    const source = `owner submission, ${nowIso.slice(0, 10)}`;

    await db.batch([
      db.prepare(
        `INSERT INTO venues (
           id, name, short_name, name_lo, type, lat, lng, area, short,
           description, photos, hours, hours_note, contact, parking, links, verified,
           status, source, updated_at, location_review, signature, pin_status
         ) VALUES (?, ?, ?, ?, ?, NULL, NULL, ?, ?, ?, '[]', ?, ?, ?, ?, ?, 0,
           NULL, ?, ?, 0, ?, 'pending')`
      ).bind(
        id, fields.name, fields.short_name || null, fields.name_lo || null,
        fields.type, fields.area || null, fields.short || null,
        fields.description || null,
        hours ? JSON.stringify(hours) : null,
        fields.hours_note || null,
        contact ? JSON.stringify(contact) : null,
        parking ? JSON.stringify(parking) : null,
        JSON.stringify(links),
        source, nowIso,
        signature ? JSON.stringify(signature) : null
      ),
      db.prepare(
        'INSERT INTO venue_owners (user_id, venue_id, granted_at) VALUES (?, ?, ?)'
      ).bind(user.id, id, nowIso),
    ]);

    // a pending venue is deliberately excluded from the public list's
    // renderMarkers/editorial sections, but it's still new data — purge so
    // it shows up in list sections/type filters right away (see
    // js/app.js renderHomeSheet) instead of waiting out the 5-minute TTL
    const publicVenuesUrl = new URL('/api/venues', context.request.url).toString();
    await caches.default.delete(new Request(publicVenuesUrl, { method: 'GET' }));

    return Response.json({
      ok: true,
      venue: {
        id, name: fields.name, short_name: fields.short_name || null,
        name_lo: fields.name_lo || null, type: fields.type,
        lat: null, lng: null, area: fields.area || null,
        short: fields.short || null, description: fields.description || null,
        photos: [], hours: hours || null, hours_note: fields.hours_note || null, links, verified: false,
        source, pin_status: 'pending',
        ...(contact ? { contact } : {}),
        ...(parking ? { parking } : {}),
        ...(signature ? { signature } : {}),
      },
    });
  } catch (e) {
    console.error(e);
    return Response.json({ ok: false, error: 'submission failed' }, { status: 500 });
  }
}

export async function onRequest(context) {
  if (context.request.method === 'GET') return handleGet(context);
  if (context.request.method === 'POST') return handlePost(context);
  return Response.json({ ok: false, error: 'method not allowed' }, { status: 405 });
}
